package com.ahotel.model;public class Booking {private Long id;private String customerName,phone,roomNumber;private int nights;public Booking(){}public Booking(Long i,String c,String p,String r,int n){id=i;customerName=c;phone=p;roomNumber=r;nights=n;}public Long getId(){return id;}public void setId(Long v){id=v;}public String getCustomerName(){return customerName;}public void setCustomerName(String v){customerName=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getRoomNumber(){return roomNumber;}public void setRoomNumber(String v){roomNumber=v;}public int getNights(){return nights;}public void setNights(int v){nights=v;}}